INSERT INTO `documents` VALUES (1,'u1dImPaqo3+qhM4kICFk6tMXPSnms33GOFQFwL7e9AM=','2026-01-20 17:43:38','2026-01-20 17:43:38',NULL,NULL,1,1,'uploaded/documents/1/1/','Confirmación _ Viva','pdf',1021130,' Resumen de la Reserva: - Número de Reserva: QHY3VA - Itinerario: Ciudad de México (NLU) → Mérida (MID) - Fecha y Hora de Salida: Mié., 1 Oct. 2025, 1:00 PM - Duración: 1h 45m - Vuelo: VB 7351, Clase E - Pasajeros: Juan Nuñez, Aida Valencia Galicia - Equipaje: 1 artículo (10 kg) - Estado: Reserva confirmada, pagada - Costo Total: $2,594.94 MXN (incluye IVA y TUA)',1,1,1),(2,'4AspCJ6Uk5dz9tnddeQOca0YdThIcuGuF26sBdwypPM=','2026-01-22 18:18:22','2026-01-22 18:18:22',NULL,NULL,2,3,'uploaded/documents/2/3/','cotizacion-43488332','pdf',37881,'Paciente: María Guadalupe Nuñez Mendoza, Femenino, 75 años. Estudio: Ultrasonido abdomen superior. Fecha: 19/01/2026. Sucursal: Marina Nacional. Precio final: 292.51 MXN (con 43% de descuento). Requisitos: Orden médica con datos del médico y paciente, ayuno mínimo de 6 horas, aseo general. Términos: No reembolso si se cancela después de 60 días; estudio válido en 60 días. Contacto: Responsable sanitario: Q.F.B. Arcadio Hernández Mata, Ced. Prof. 5703872 UNAM.',1,1,1),(3,'HuH4UCPzku9bebCSk2+EG3UnuiG764aHrPxnZ6ZtBoA=','2026-01-23 18:02:49','2026-01-23 18:02:49',NULL,NULL,1,1,'uploaded/documents/1/1/','CV_2026_JJNM','pdf',88044,' Juan de Jesús Núñez Mendoza - Ingeniero mecánico con experiencia en desarrollo de software, análisis de datos, backend, APIs, criptografía, automatización y web scraping. - Experiencia en inteligencia de negocios, sistemas embebidos, NLP, machine learning, algoritmos criptográficos, firmas electrónicas y servicios en la nube. - Líder de desarrollo backend en Notaría 230 (2024-2025), enfocado en refactorización, seguridad y optimización de sistemas. - Programador Python Sr. en Coppel (2024) y Intermedia México (2022-2024), con desarrollo de APIs, web scraping, transcripción automática y análisis de redes sociales. - Fundador, CEO y CTO de SignForce (2021), plataforma SaaS de firmas electrónicas avanzadas y gestión documental. - Experiencia técnica: Python, Go, SQL, MongoDB, Docker, FastAPI, Flask, Linux, Git, NLP, machine learning, criptografía y ciberseguridad. - Educación: Ingeniería Mecánica (IPN ESIME Azcapotzalco, 2011-2017). - Proyectos destacados: Middleware para firmas electrónicas avanzadas (NOM 151, RFC 3161), herramienta de extracción de redes sociales, sistema de transcripción automática y digitalización documental. - Contacto: Teléfono 52 5529996911 Correo: do.c.001@hotmail.com Residencia: Colonia Granada, CDMX.',1,1,1),(4,'DDUgZ6JF/tfIg1E2CAThpe69QzHt8yHUL/COutRKcAA=','2026-01-23 18:02:49','2026-01-23 18:02:49',NULL,NULL,1,1,'uploaded/documents/1/1/','CV_MariaBarrera','pdf',80806,' MARÍA BARRERA Mexico City, Mexico 52 2024-110-0715 mbaarrera415@gmail.com linkedin.com/in/MariaBarrera415 Professional Summary Sales executive with 5 years of B2B experience in leading tech companies such as Salesforce, SAP, and Microsoft. Proven track record in managing full sales cycles, engaging C-level executives, and closing complex deals. Adept at building strategic client relationships and consistently exceeding revenue targets across multi-industry territories. Fluent in English and Spanish, with international exposure and strong analytical skills. Professional Experience - Sr. Account Executive – Salesforce (2024 – Present) - Manage full end-to-end sales cycles for enterprise accounts, targeting C-level executives and delivering Salesforce Marketing Cloud solutions. - Managed full sales process, engaging Sales Engineers, Professional Services, Marketing, and Partners to deliver optimal client solutions. - Leveraged solution selling expertise to address customer needs, identifying business potential and establishing long-term strategic partnerships. - Strengthened client relationships through regular engagement and face-to-face meetings, enhancing customer satisfaction and retention. - Sr. Account Executive – SAP (2021 – 2024) - Managed end-to-end sales cycles for Enterprise Accounts in industries such as Manufacturing, Retail, and Travel & Hospitality. - Achieved 100% or more of yearly quota for three consecutive years, measured by Services Bookings, implementing solutions such as SuccessFactors, S/4HANA, BTP, and Ariba. - Led a value-added team of co-prime Solution Advisors, resulting in a pipeline coverage of over 3.5x. - Managed an annual quota ranging between 4 to 6 million euros. - Recognized with multiple awards including \'Linearity Award\' and \'Strategic Deal of the Year\'. - Customer Success Account Manager – Microsoft (2019 – 2020) - Fostered strategic relationships with key stakeholders to ensure successful solution delivery. - Achieved 100% renewal rate in Key Accounts and drove cloud consumption initiatives. - Forecasted and monitored incident usage across accounts, ensuring operational efficiency. - Accelerated cloud consumption through targeted campaigns and client stakeholder follow-up. Education - MBA – Tecnológico de Monterrey (2024 – Present) - B.S. Industrial Engineering – Tecnológico de Monterrey (2016 – 2020) - Project and Operation Management – Institut National Polytechnique de Toulouse (2019) Skills & Certifications - Salesforce SAP Power BI Excel Account Planning Pipeline Management Value Selling Communication SCRUM Fundamentals SAP Material Management SAP Financial Accounting Languages - Spanish (Native), English (Fluent), Japanese (Basic)',1,1,1),(5,'OL+iwK5iTq2U1rUre1DJ5BkS++t2xozI1C89HSiayQw=','2026-01-23 18:02:49','2026-01-23 18:02:49',NULL,NULL,1,1,'uploaded/documents/1/1/','mifiel_Tabla+de+precios+2023','pdf',3521706,'### Documentos Cantidad Precio por documento (MXN) Precio del paquete (MXN) ----------|----------------------------|--------------------------- 10 $89 $890 50 $79 $3,950 100 $59 $5,900 500 $29 $14,500 1,000 $19 $19,000 5,000 $12 $60,000 10,000 $9 $90,000 25,000 $7 $175,000 50,000 $5.80 $2