INSERT INTO `statusinstitution` VALUES (1,'Nulo','1','Sin estatus o no requiere'),(2,'PENDIENTE_REGISTRO','1','El usuario inició el registro pero no lo completó (por ejemplo, aún no verificó el correo o no llenó todos los datos).'),(3,'REVISION_REGISTRO','1','El usuario ya completo sus datos y subió sus documentos de identidad, comprobante de domicilio, etc., pero están en revisión.'),(4,'RECHAZO_DOCUMENTOS','0','Algún documento fue rechazado por ser ilegible, inválido o por no coincidir con los datos del usuario. Se debe permitir que el usuario los reenvíe.'),(5,'PLAN_PAGO','1','Falta plan de pago. El contrato fue firmado y registrado correctamente (puede incluir sello de tiempo y almacenamiento del documento).'),(6,'LLAVES','1','El usuario está verificado pero aún no ha subido la llave del usuario root.'),(7,'ACTIVO','1','Usuario completamente habilitado para operar dentro del sistema (por ejemplo, puede firmar documentos, generar sellos de tiempo, etc.).'),(8,'SUSPENDIDO','0','Usuario que fue suspendido temporalmente por problemas administrativos, seguridad o requerimientos legales.'),(9,'BAJA','1','Usuario que fue dado de baja o canceló su cuenta voluntariamente.'),(10,'REVOCADO','0','Usuario que se le retiró el servicio por alguna causa especificada.'),(11,'RECHAZADO','1','Usuario rechazado por motivos de pago');
/*!40000 ALTER TABLE `statusinstitution` ENABLE KEYS */;
